{
  "findings": [
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that users under 13 can no longer directly message others outside of games or experiences, only using broadcast public chat, and must have parental consent for direct messaging within experiences.",
      "stance": "risk",
      "quote": "users under the age of 13 will no longer able to directly message others on Roblox outside of games or experiences (also known as platform chat). When communicating in a game or experience, users under the age of 13 will be able to communicate using the broadcast public chat. To use direct messaging within experiences, users under 13 will need parental consent."
    },
    {
      "ref": "[D540]",
      "area": "contact",
      "claim": "A parent reports that the ability to message each other via the Roblox Inbox has been removed and the legacy chat system will be removed by April 30.",
      "stance": "risk",
      "quote": "we’ve [removed](https://devforum.roblox.com/t/sunsetting-user-to-user-inbox-messaging/3187502?page=3) the ability for users to message each other via the Roblox Inbox and are removing the legacy chat system by **April 30**."
    },
    {
      "ref": "[D540]",
      "area": "money",
      "claim": "A parent reports that the developer removed the parent PIN feature without replacement, which was a security measure that helped prevent account lockout after a birthday change to under 13.",
      "stance": "risk",
      "quote": "As previously announced over email, as of today, you are no longer able to set or use a parent PIN on your Roblox account. As always, if you are interested in an added layer of security on your account, you can [set up 2-factor authentication](https://en.help.roblox.com/hc/en-us/articles/212459863-Add-2-Step-Verification-to-Your-Account)."
    },
    {
      "ref": "[D540]",
      "area": "data",
      "claim": "A parent reports that the developer states parental controls can be managed remotely and that linking accounts requires verification via ID or credit card, implying data collection for verification.",
      "stance": "neutral",
      "quote": "Parents who want to be more involved in monitoring their child’s activities can link their Roblox account to their child’s account after verifying themselves using an ID or credit card."
    },
    {
      "ref": "[D540]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate for users under 13 is enforced by filtering out experiences without content maturity labels from search and recommendations for those users.",
      "stance": "mitigation",
      "quote": "All experiences without content maturity labels will be filtered out of search and any public or recommended sorts for users under 13."
    },
    {
      "ref": "[D540]",
      "area": "content",
      "claim": "A parent reports that reviewers note the new content labels are Minimal, Mild, Moderate, and Restricted, replacing the previous Age Guidelines.",
      "stance": "neutral",
      "quote": "we’ve begun labeling experiences based on the type of content available on Roblox, rather than by age. Experience Guidelines are now called Content Labels, which is reflected in the questionnaire you fill out for your experience. “Age Guidelines” is now called “Content Maturity”, and users will continue to be able to customize their access to experiences based on their Content Maturity setting under Parental Controls. The new content labels are now Minimal, Mild, Moderate, and Restricted."
    },
    {
      "ref": "[D540]",
      "area": "developer_record",
      "claim": "A parent reports that the developer announced updates to safety protections and parental controls, indicating ongoing regulatory focus on child safety.",
      "stance": "neutral",
      "quote": "we are sharing the latest updates to our safety controls, including significant improvements to parental controls, how users under age 13 can communicate on Roblox, new content labels, and built-in protections for younger users."
    }
  ]
}
